/// Detect conflicts between I002 (missing-required-import) and PYI025 (unaliased-collections-abc-set-import).
///
/// PYI025 requires that `from collections.abc import Set` be aliased as `AbstractSet`. If the same
/// import is listed unaliased in `lint.isort.required-imports`, the two rules pull in opposite
/// directions, so we surface a configuration error rather than silently fighting over the import.
fn conflicting_required_import_and_pyi025(
    isort: &isort::settings::Settings,
    rules: &RuleTable,
) -> Result<()> {
    if !rules.enabled(Rule::UnaliasedCollectionsAbcSetImport) {
        return Ok(());
    }

    for required_import in &isort.required_imports {
        // PYI025 fires on `from collections.abc import Set` unless it's aliased as `AbstractSet`.
        if matches!(
            required_import.qualified_name().segments(),
            ["collections", "abc", "Set"]
        ) && required_import.bound_name() != "AbstractSet"
        {
            return Err(anyhow!(
                "Required import `from collections.abc import Set` specified in \
                `lint.isort.required-imports` (I002) conflicts with \
                `unaliased-collections-abc-set-import` (PYI025), which requires this import to be \
                aliased as `AbstractSet`.\n\
                Either alias the required import (`from collections.abc import Set as AbstractSet`), \
                or disable PYI025."
            ));
        }
    }

    Ok(())
}

